// ─── SESSION TOKEN ────────────────────────────────────────────────────────────
async function hmacSign(data, secret) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(data));
  return btoa(String.fromCharCode(...new Uint8Array(sig)))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}

async function createToken(pinLevel, secret) {
  const now = Math.floor(Date.now() / 1000);
  const payload = btoa(JSON.stringify({ pin_level: pinLevel, iat: now, exp: now + SESSION_TTL }))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
  const sig = await hmacSign(payload, secret);
  return payload + '.' + sig;
}

async function verifyToken(token, secret) {
  if (!token) return null;
  const parts = token.split('.');
  if (parts.length !== 2) return null;
  const [payload, sig] = parts;
  const expectedSig = await hmacSign(payload, secret);
  if (sig !== expectedSig) return null;
  try {
    const data = JSON.parse(atob(payload.replace(/-/g, '+').replace(/_/g, '/')));
    if (Math.floor(Date.now() / 1000) > data.exp) return null;
    return data;
  } catch { return null; }
}

const SESSION_TTL = 2592000; // 30 days

// ─── AUTH HANDLER ─────────────────────────────────────────────────────────────
async function handleAuth(request, env) {
  const body = await request.json().catch(() => ({}));
  const { pin, pin_type } = body;

  if (!pin || !pin_type) {
    return cors(new Response(JSON.stringify({ error: 'Missing pin or pin_type' }), {
      status: 400, headers: { 'Content-Type': 'application/json' }
    }));
  }

  const pinMap = {
    ops:    env.PIN_OPS,
    mgmt:   env.PIN_MGMT,
    mobile: env.PIN_MOBILE,
    price:  env.PRICE_PIN,
  };

  const correctPin = pinMap[pin_type];
  if (!correctPin || pin !== correctPin) {
    return cors(new Response(JSON.stringify({ error: 'Invalid PIN' }), {
      status: 401, headers: { 'Content-Type': 'application/json' }
    }));
  }

  // price PIN grants mgmt-level access (repricer operators)
  const tokenLevel = pin_type === 'price' ? 'mgmt' : pin_type;
  const token = await createToken(tokenLevel, env.SESSION_SECRET);
  return cors(new Response(JSON.stringify({ token, pin_level: pin_type }), {
    headers: { 'Content-Type': 'application/json' }
  }));
}

// ═══════════════════════════════════════════════════════════════════════════════
// ── CREDENTIAL-BASED AUTH (NEW) ───────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════
// Separate, parallel system alongside the existing PIN-based auth above.
// The existing createToken/verifyToken are stateless (signed payload only,
// no server-side record) - that works fine for the fixed-30-day PIN
// sessions, but can't support what real accounts need: a 1-hour ROLLING
// expiry (extends on activity) and explicit logout (shared devices get
// handed between workers mid-shift, so the next person needs a clean
// slate). Both require a real, server-side session record - hence a D1
// `cred_sessions` table here instead of another signed-payload token.
// Existing apps keep using the PIN system untouched; each app migrates
// to this one individually as it gets updated.

const CRED_SESSION_ROLLING_MINUTES = 60;
// Login rate limiting - after this many consecutive failed attempts for a
// given username within the window below, further attempts are rejected
// without even checking the password, until the window elapses. A real
// person who mistypes a password a few times will never hit 10; this only
// stops sustained automated guessing.
const LOGIN_MAX_FAILED_ATTEMPTS = 10;
const LOGIN_LOCKOUT_WINDOW_MINUTES = 15;

async function ensureCredAuthTables(env) {
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS cred_users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL UNIQUE,
      password_hash TEXT NOT NULL,
      display_name TEXT NOT NULL,
      active INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL,
      last_login TEXT
    )
  `).run().catch(()=>{});
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS cred_user_roles (
      user_id INTEGER NOT NULL,
      role TEXT NOT NULL,
      PRIMARY KEY (user_id, role)
    )
  `).run().catch(()=>{});
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS cred_sessions (
      token TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      created_at TEXT NOT NULL,
      last_active TEXT NOT NULL
    )
  `).run().catch(()=>{});
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_cred_sessions_user ON cred_sessions(user_id)`).run().catch(()=>{});
  // Login rate limiting - tracks failed attempts per username to slow
  // brute-force guessing. Not IP-based: Workers don't reliably expose a
  // stable client IP, and username-based limiting still protects each
  // individual account regardless of where attempts come from.
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS cred_login_attempts (
      username TEXT PRIMARY KEY,
      fail_count INTEGER NOT NULL DEFAULT 0,
      first_fail_at TEXT NOT NULL
    )
  `).run().catch(()=>{});
}

// ── Levels (Worker / Pro / Admin / Owner) ─────────────────────────────────
// A level is a named preset of the existing permission roles every page
// and route already checks (mobile, ops, mgmt, price, admin) — so nothing
// downstream changes: a person's roles are now
//     their level's roles  ∪  their own extra roles (cred_user_roles).
// cred_user_roles keeps meaning "this person's own boxes"; for people who
// had roles before levels existed that's exactly their old set, so giving
// them a level can only ever ADD access, never silently remove it.
// Owner is special: always includes admin, plus the 'owner' role, which
// only Owners have and which gates changing levels / Admin / Owner people.
const CRED_PERMS = ['mobile', 'ops', 'mgmt', 'price', 'admin'];
const CRED_LEVEL_DEFAULTS = [
  { key: 'worker', name: 'Worker', rank: 1, roles: ['mobile', 'ops'] },
  { key: 'pro',    name: 'Pro',    rank: 2, roles: ['mobile', 'ops', 'mgmt'] },
  { key: 'admin',  name: 'Admin',  rank: 3, roles: ['mobile', 'ops', 'mgmt', 'price', 'admin'] },
  { key: 'owner',  name: 'Owner',  rank: 4, roles: ['mobile', 'ops', 'mgmt', 'price', 'admin'] },
];
let _credLevelTablesReady = false;
async function ensureCredLevelTables(env) {
  if (_credLevelTablesReady) return;
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS cred_levels (
    key TEXT PRIMARY KEY, name TEXT NOT NULL, rank INTEGER NOT NULL, roles TEXT NOT NULL)`).run().catch(()=>{});
  for (const l of CRED_LEVEL_DEFAULTS) {
    await env.DB.prepare(`INSERT OR IGNORE INTO cred_levels (key, name, rank, roles) VALUES (?, ?, ?, ?)`)
      .bind(l.key, l.name, l.rank, JSON.stringify(l.roles)).run().catch(()=>{});
  }
  await env.DB.prepare(`ALTER TABLE cred_users ADD COLUMN level TEXT`).run().catch(()=>{});
  // Removed users (Admin → Users → Remove): the row stays so old History /
  // logs still show who did what; deleted_at hides it from the Users list.
  await env.DB.prepare(`ALTER TABLE cred_users ADD COLUMN deleted_at TEXT`).run().catch(()=>{});
  await env.DB.prepare(`ALTER TABLE cred_users ADD COLUMN deleted_by TEXT`).run().catch(()=>{});
  _credLevelTablesReady = true;
}

async function credGetLevels(env) {
  await ensureCredLevelTables(env);
  const rows = (await env.DB.prepare(`SELECT key, name, rank, roles FROM cred_levels ORDER BY rank`).all()).results || [];
  const out = {};
  for (const r of rows) {
    let roles = []; try { roles = JSON.parse(r.roles || '[]'); } catch (_) {}
    roles = roles.filter(x => CRED_PERMS.includes(x));
    if (r.key === 'owner' && !roles.includes('admin')) roles.push('admin');
    out[r.key] = { key: r.key, name: r.name, rank: r.rank, roles };
  }
  return out;
}

// Everything a person can do: level roles + their own extra roles.
async function credEffectiveRoles(env, user, levels) {
  levels = levels || await credGetLevels(env);
  const own = ((await env.DB.prepare(`SELECT role FROM cred_user_roles WHERE user_id = ?`).bind(user.id).all()).results || []).map(r => r.role);
  const lvl = user.level && levels[user.level];
  const set = new Set([...(lvl ? lvl.roles : []), ...own]);
  if (user.level === 'owner') { set.add('admin'); set.add('owner'); }
  return [...set];
}

async function credOwnerCount(env) {
  await ensureCredLevelTables(env);
  const r = await env.DB.prepare(`SELECT COUNT(*) AS n FROM cred_users WHERE level = 'owner' AND active = 1`).first();
  return (r && r.n) || 0;
}

// Owners can do everything. While NO owner exists yet (first setup), any
// admin may act as one — that's how the first Owner gets assigned.
async function credCanActAsOwner(env, session) {
  if (session && session.roles && session.roles.includes('owner')) return true;
  return (await credOwnerCount(env)) === 0;
}

// ── Pages & tabs a person may NOT see ────────────────────────────────────
// access_rules rows: scope 'level:<key>' (allow=0 → that level can't see
// the item) or 'user:<id>' (allow=0 hide / allow=1 show, overriding the
// level for that one person). Items are page keys ("packship") or
// page:tab keys ("packship:status") from the catalog in xf-access.js.
// Owners always see everything. This hides things in the apps; what the
// server allows is still decided by the permission roles above.
let _accessTableReady = false;
async function ensureAccessTable(env) {
  if (_accessTableReady) return;
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS access_rules (
    scope TEXT NOT NULL, item TEXT NOT NULL, allow INTEGER NOT NULL, PRIMARY KEY (scope, item))`).run().catch(()=>{});
  _accessTableReady = true;
}
async function accessBlockedFor(env, userId, level) {
  if (level === 'owner') return [];
  await ensureAccessTable(env);
  const rows = (await env.DB.prepare(`SELECT scope, item, allow FROM access_rules WHERE scope = ? OR scope = ?`)
    .bind('level:' + (level || '-'), 'user:' + userId).all()).results || [];
  const blocked = new Set(rows.filter(r => r.scope.startsWith('level:') && !r.allow).map(r => r.item));
  for (const r of rows.filter(r => r.scope.startsWith('user:'))) { if (r.allow) blocked.delete(r.item); else blocked.add(r.item); }
  return [...blocked];
}

// PBKDF2 password hashing - native to the Workers runtime via Web Crypto,
// no external library needed. Per-user random salt, stored as "salt:hash".
async function hashPassword(password, saltHex) {
  const enc = new TextEncoder();
  let salt;
  if (saltHex) {
    salt = new Uint8Array(saltHex.match(/.{2}/g).map(b => parseInt(b, 16)));
  } else {
    salt = crypto.getRandomValues(new Uint8Array(16));
  }
  const keyMaterial = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' },
    keyMaterial, 256
  );
  const hashHex = [...new Uint8Array(bits)].map(b => b.toString(16).padStart(2, '0')).join('');
  const saltHexOut = [...salt].map(b => b.toString(16).padStart(2, '0')).join('');
  return `${saltHexOut}:${hashHex}`;
}

async function verifyPassword(password, stored) {
  const [saltHex, hashHex] = (stored || '').split(':');
  if (!saltHex || !hashHex) return false;
  const recomputed = await hashPassword(password, saltHex);
  const recomputedHash = recomputed.split(':')[1];
  return recomputedHash === hashHex;
}

function newSessionToken() {
  return [...crypto.getRandomValues(new Uint8Array(32))].map(b => b.toString(16).padStart(2, '0')).join('');
}

// POST /auth/login  { username, password } -> { token, displayName, roles }
async function credLogin(request, env) {
  await ensureCredAuthTables(env);
  const body = await request.json().catch(() => ({}));
  const { username, password } = body;
  if (!username || !password) {
    return cors(new Response(JSON.stringify({ error: 'Username and password required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  const normalizedUsername = username.trim().toLowerCase();

  // Rate limit check - before touching the password at all
  const attemptRow = await env.DB.prepare(`SELECT * FROM cred_login_attempts WHERE username = ?`).bind(normalizedUsername).first();
  if (attemptRow) {
    const windowAgeMinutes = (Date.now() - new Date(attemptRow.first_fail_at).getTime()) / 60000;
    if (windowAgeMinutes < LOGIN_LOCKOUT_WINDOW_MINUTES && attemptRow.fail_count >= LOGIN_MAX_FAILED_ATTEMPTS) {
      return cors(new Response(JSON.stringify({ error: 'Too many failed attempts. Try again in a few minutes.' }), { status: 429, headers: { 'Content-Type': 'application/json' } }));
    }
  }

  const user = await env.DB.prepare(`SELECT * FROM cred_users WHERE username = ? AND active = 1`).bind(normalizedUsername).first();
  if (!user || !(await verifyPassword(password, user.password_hash))) {
    // Record the failure - reset the window if the old one has expired,
    // otherwise increment the existing count.
    const windowAgeMinutes = attemptRow ? (Date.now() - new Date(attemptRow.first_fail_at).getTime()) / 60000 : Infinity;
    if (!attemptRow || windowAgeMinutes >= LOGIN_LOCKOUT_WINDOW_MINUTES) {
      await env.DB.prepare(`INSERT INTO cred_login_attempts (username, fail_count, first_fail_at) VALUES (?, 1, ?) ON CONFLICT(username) DO UPDATE SET fail_count = 1, first_fail_at = ?`)
        .bind(normalizedUsername, new Date().toISOString(), new Date().toISOString()).run().catch(()=>{});
    } else {
      await env.DB.prepare(`UPDATE cred_login_attempts SET fail_count = fail_count + 1 WHERE username = ?`).bind(normalizedUsername).run().catch(()=>{});
    }
    return cors(new Response(JSON.stringify({ error: 'Invalid username or password' }), { status: 401, headers: { 'Content-Type': 'application/json' } }));
  }

  // Successful login - clear any recorded failures for this username
  if (attemptRow) {
    await env.DB.prepare(`DELETE FROM cred_login_attempts WHERE username = ?`).bind(normalizedUsername).run().catch(()=>{});
  }

  const roles = await credEffectiveRoles(env, user);

  const token = newSessionToken();
  const now = new Date().toISOString();
  await env.DB.prepare(`INSERT INTO cred_sessions (token, user_id, created_at, last_active) VALUES (?, ?, ?, ?)`).bind(token, user.id, now, now).run();
  await env.DB.prepare(`UPDATE cred_users SET last_login = ? WHERE id = ?`).bind(now, user.id).run();

  return cors(new Response(JSON.stringify({
    token, userId: user.id, username: user.username, displayName: user.display_name, roles, level: user.level || null,
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /auth/logout  { token } -> explicit invalidation, needed for shared devices
async function credLogout(request, env) {
  await ensureCredAuthTables(env);
  const body = await request.json().catch(() => ({}));
  const token = body.token || request.headers.get('X-Cred-Token');
  if (!token) return cors(new Response(JSON.stringify({ ok: false, error: 'token required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  await env.DB.prepare(`DELETE FROM cred_sessions WHERE token = ?`).bind(token).run();
  return cors(new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } }));
}

// Shared session-check helper every migrated route calls. Rolling expiry:
// a valid check extends last_active to now, so an actively-used session
// never expires mid-task - only genuine inactivity (60+ min untouched)
// logs someone out.
async function verifyCredSession(token, env) {
  if (!token) return null;
  await ensureCredAuthTables(env);
  const session = await env.DB.prepare(`SELECT * FROM cred_sessions WHERE token = ?`).bind(token).first();
  if (!session) return null;
  const lastActive = new Date(session.last_active).getTime();
  const ageMinutes = (Date.now() - lastActive) / 60000;
  if (ageMinutes > CRED_SESSION_ROLLING_MINUTES) {
    await env.DB.prepare(`DELETE FROM cred_sessions WHERE token = ?`).bind(token).run(); // expired - clean up
    return null;
  }
  const user = await env.DB.prepare(`SELECT * FROM cred_users WHERE id = ? AND active = 1`).bind(session.user_id).first();
  if (!user) return null;
  const roles = await credEffectiveRoles(env, user);

  await env.DB.prepare(`UPDATE cred_sessions SET last_active = ? WHERE token = ?`).bind(new Date().toISOString(), token).run(); // rolling extension

  return { userId: user.id, username: user.username, displayName: user.display_name, roles, level: user.level || null };
}

// (Placeholder account bootstrap removed - real accounts with all roles
// now exist, and this route was a genuine risk to leave reachable: if
// cred_users ever momentarily emptied, it would silently recreate the
// well-known testadmin/ChangeMe123! account with full admin access,
// unauthenticated, and return the password in plain text in the response.)

// ═══════════════════════════════════════════════════════════════════════════════
// ── USER ACTIVITY LOG (foundation for performance tracking) ─────────────────
// ═══════════════════════════════════════════════════════════════════════════════
// Generic, reusable log any future migrated app/route can write a single
// row to - one consistent table instead of bespoke per-app reporting
// later. Genuinely empty until an app is actually migrated to call
// logUserActivity() on its real actions (scans, receives, price changes,
// etc.) - login/logout alone don't populate this with anything useful.
async function ensureActivityLogTable(env) {
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS user_activity_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      action_type TEXT NOT NULL,
      timestamp TEXT NOT NULL,
      metadata TEXT
    )
  `).run().catch(()=>{});
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_activity_user ON user_activity_log(user_id)`).run().catch(()=>{});
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_activity_type_time ON user_activity_log(action_type, timestamp)`).run().catch(()=>{});
}

// Call this from any migrated route after a real action completes.
// metadata is a plain JS object - anything relevant to that action type
// (e.g. { tracking, carrier } for a scan, { partNum, cases } for a receive).
async function logUserActivity(env, userId, actionType, metadata) {
  try {
    await ensureActivityLogTable(env);
    await env.DB.prepare(`INSERT INTO user_activity_log (user_id, action_type, timestamp, metadata) VALUES (?, ?, ?, ?)`)
      .bind(userId, actionType, new Date().toISOString(), JSON.stringify(metadata || {})).run();
  } catch (_) { /* never let logging break the real action */ }
}

// ═══════════════════════════════════════════════════════════════════════════════
// ── ADMIN: USER MANAGEMENT (all routes require a valid session with the
// ── 'admin' role - checked in the route dispatcher, not here)
// ═══════════════════════════════════════════════════════════════════════════════

// GET /admin/users/list
async function adminListUsers(env, session) {
  await ensureCredAuthTables(env);
  const levels = await credGetLevels(env);
  const users = await env.DB.prepare(`SELECT id, username, display_name, active, created_at, last_login, level, deleted_at, deleted_by FROM cred_users ORDER BY username ASC`).all();
  const rolesRes = await env.DB.prepare(`SELECT user_id, role FROM cred_user_roles`).all();
  const rolesByUser = {};
  for (const r of (rolesRes.results || [])) {
    (rolesByUser[r.user_id] = rolesByUser[r.user_id] || []).push(r.role);
  }
  const result = (users.results || []).map(u => {
    const extra = rolesByUser[u.id] || [];
    const lvl = u.level && levels[u.level];
    const eff = new Set([...(lvl ? lvl.roles : []), ...extra]);
    if (u.level === 'owner') { eff.add('admin'); eff.add('owner'); }
    return {
      id: u.id, username: u.username, displayName: u.display_name,
      active: !!u.active, createdAt: u.created_at, lastLogin: u.last_login,
      level: u.level || null, extraRoles: extra, roles: [...eff],
      removedAt: u.deleted_at || null, removedBy: u.deleted_by || null,
    };
  });
  const ownerCount = result.filter(u => u.level === 'owner' && u.active).length;
  return cors(new Response(JSON.stringify({
    ok: true, users: result, levels: Object.values(levels), perms: CRED_PERMS,
    ownerCount, youCanManageLevels: await credCanActAsOwner(env, session),
  }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /admin/users/create  { username, password, displayName, roles: [] }
async function adminCreateUser(request, env, session) {
  await ensureCredAuthTables(env);
  const body = await request.json().catch(() => ({}));
  const { username, password, displayName, roles } = body;
  const levels = await credGetLevels(env);
  const level = body.level || null;
  if (level && !levels[level]) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Unknown level' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  const ownerPowers = await credCanActAsOwner(env, session);
  if ((level === 'admin' || level === 'owner' || (roles || []).includes('admin')) && !ownerPowers) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Only an Owner can create Admin or Owner accounts' }), { status: 403, headers: { 'Content-Type': 'application/json' } }));
  }
  if (!username || !password || !displayName) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'username, password, and displayName required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  // Owner: a 4-digit number is OK (sign-in still locks after too many wrong tries).
  if (String(password).length < 4) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Password must be at least 4 characters (a 4-digit number is OK)' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  const uname = username.trim().toLowerCase();
  await ensureCredLevelTables(env);
  const existing = await env.DB.prepare(`SELECT id, deleted_at FROM cred_users WHERE username = ?`).bind(uname).first();
  if (existing && existing.deleted_at) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'A removed user already has this username — open "Show removed users" and Restore them instead' }), { status: 409, headers: { 'Content-Type': 'application/json' } }));
  }
  if (existing) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Username already exists' }), { status: 409, headers: { 'Content-Type': 'application/json' } }));
  }
  const hash = await hashPassword(password);
  const now = new Date().toISOString();
  const result = await env.DB.prepare(`INSERT INTO cred_users (username, password_hash, display_name, active, created_at, level) VALUES (?, ?, ?, 1, ?, ?)`)
    .bind(uname, hash, displayName.trim(), now, level).run();
  const userId = result.meta.last_row_id;
  const validRoles = ['ops', 'mgmt', 'mobile', 'price', 'admin'];
  for (const role of (roles || [])) {
    if (validRoles.includes(role)) {
      await env.DB.prepare(`INSERT INTO cred_user_roles (user_id, role) VALUES (?, ?)`).bind(userId, role).run();
    }
  }
  return cors(new Response(JSON.stringify({ ok: true, userId, username: uname }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /admin/users/reset-password  { userId, newPassword }
async function adminResetPassword(request, env, session) {
  await ensureCredAuthTables(env);
  const body = await request.json().catch(() => ({}));
  const { userId, newPassword } = body;
  // Resetting an Admin's / Owner's password would let an Admin take over
  // that account — Owner only.
  await ensureCredLevelTables(env);
  const t = userId ? await env.DB.prepare(`SELECT level FROM cred_users WHERE id = ?`).bind(userId).first() : null;
  if (t && (t.level === 'admin' || t.level === 'owner') && !(await credCanActAsOwner(env, session))) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Only an Owner can reset an Admin or Owner password' }), { status: 403, headers: { 'Content-Type': 'application/json' } }));
  }
  if (!userId || !newPassword) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'userId and newPassword required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  // Owner: a 4-digit number is OK (sign-in still locks after too many wrong tries).
  if (String(newPassword).length < 4) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Password must be at least 4 characters (a 4-digit number is OK)' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  const hash = await hashPassword(newPassword);
  const result = await env.DB.prepare(`UPDATE cred_users SET password_hash = ? WHERE id = ?`).bind(hash, userId).run();
  if (!result.meta.changes) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'User not found' }), { status: 404, headers: { 'Content-Type': 'application/json' } }));
  }
  // Reset password also invalidates all existing sessions for this user -
  // a compromised or forgotten password shouldn't leave old sessions valid.
  await env.DB.prepare(`DELETE FROM cred_sessions WHERE user_id = ?`).bind(userId).run();
  // …and clears the "too many failed attempts" lock (owner: "reset Yola's
  // password, why still not working?" — after the wrong tries she stayed
  // locked out for 15 minutes even with the new password).
  const un = await env.DB.prepare(`SELECT username FROM cred_users WHERE id = ?`).bind(userId).first();
  if (un) await env.DB.prepare(`DELETE FROM cred_login_attempts WHERE username = ?`).bind(String(un.username).trim().toLowerCase()).run().catch(() => {});
  return cors(new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /admin/users/update-roles  { userId, roles: [] }  — replaces the full role set
async function adminUpdateRoles(request, env, session) {
  await ensureCredAuthTables(env);
  const body = await request.json().catch(() => ({}));
  const { userId, roles } = body;
  if (!userId || !Array.isArray(roles)) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'userId and roles array required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  const validRoles = ['ops', 'mgmt', 'mobile', 'price', 'admin'];
  const cleanRoles = [...new Set(roles.filter(r => validRoles.includes(r)))];
  const deny = msg => cors(new Response(JSON.stringify({ ok: false, error: msg }), { status: 403, headers: { 'Content-Type': 'application/json' } }));

  // Level (optional in the request — older callers only send roles).
  const levels = await credGetLevels(env);
  const target = await env.DB.prepare(`SELECT id, level, active FROM cred_users WHERE id = ?`).bind(userId).first();
  if (!target) return cors(new Response(JSON.stringify({ ok: false, error: 'User not found' }), { status: 404, headers: { 'Content-Type': 'application/json' } }));
  const hasLevel = Object.prototype.hasOwnProperty.call(body, 'level');
  const newLevel = hasLevel ? (body.level || null) : (target.level || null);
  if (newLevel && !levels[newLevel]) return cors(new Response(JSON.stringify({ ok: false, error: 'Unknown level' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  const ownerPowers = await credCanActAsOwner(env, session);
  const high = l => l === 'admin' || l === 'owner';
  if ((high(newLevel) || high(target.level)) && newLevel !== target.level && !ownerPowers) return deny('Only an Owner can give or take away the Admin or Owner level');
  if (high(target.level) && !ownerPowers) return deny('Only an Owner can change an Admin or Owner');
  const oldOwn = ((await env.DB.prepare(`SELECT role FROM cred_user_roles WHERE user_id = ?`).bind(userId).all()).results || []).map(r => r.role);
  if (cleanRoles.includes('admin') !== oldOwn.includes('admin') && !ownerPowers) return deny('Only an Owner can give or take away Admin access');
  if (target.level === 'owner' && newLevel !== 'owner' && target.active && (await credOwnerCount(env)) <= 1) return deny('This is the last Owner — make someone else Owner first');
  if (hasLevel) await env.DB.prepare(`UPDATE cred_users SET level = ? WHERE id = ?`).bind(newLevel, userId).run();
  await env.DB.prepare(`DELETE FROM cred_user_roles WHERE user_id = ?`).bind(userId).run();
  for (const role of cleanRoles) {
    await env.DB.prepare(`INSERT INTO cred_user_roles (user_id, role) VALUES (?, ?)`).bind(userId, role).run();
  }
  return cors(new Response(JSON.stringify({ ok: true, roles: cleanRoles }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /admin/levels/update  { levels: [{ key, roles: [...] }] } — what each
// level can do. Owner only (or any admin while no Owner exists yet).
async function adminUpdateLevels(request, env, session) {
  if (!(await credCanActAsOwner(env, session))) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Only an Owner can change what each level can do' }), { status: 403, headers: { 'Content-Type': 'application/json' } }));
  }
  const body = await request.json().catch(() => ({}));
  const levels = await credGetLevels(env);
  for (const l of (Array.isArray(body.levels) ? body.levels : [])) {
    if (!levels[l.key]) continue;
    let roles = [...new Set((l.roles || []).filter(r => CRED_PERMS.includes(r)))];
    if (l.key === 'owner' && !roles.includes('admin')) roles.push('admin'); // an Owner can always reach this page
    await env.DB.prepare(`UPDATE cred_levels SET roles = ? WHERE key = ?`).bind(JSON.stringify(roles), l.key).run();
  }
  return cors(new Response(JSON.stringify({ ok: true, levels: Object.values(await credGetLevels(env)) }), { headers: { 'Content-Type': 'application/json' } }));
}

// GET /admin/access — every page/tab rule, by scope.
async function adminGetAccess(env) {
  await ensureAccessTable(env);
  const rows = (await env.DB.prepare(`SELECT scope, item, allow FROM access_rules`).all()).results || [];
  const rules = {};
  for (const r of rows) (rules[r.scope] = rules[r.scope] || {})[r.item] = r.allow ? 1 : 0;
  return cors(new Response(JSON.stringify({ ok: true, rules }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /admin/access/save { scope: 'level:worker' | 'user:12', rules: { item: 0|1 } }
// Replaces all rules for that scope. Levels (and Admin/Owner people): Owner only.
async function adminSaveAccess(request, env, session) {
  await ensureAccessTable(env);
  const b = await request.json().catch(() => ({}));
  const scope = String(b.scope || '');
  const deny = (msg, st) => cors(new Response(JSON.stringify({ ok: false, error: msg }), { status: st || 403, headers: { 'Content-Type': 'application/json' } }));
  const ownerPowers = await credCanActAsOwner(env, session);
  let m;
  if ((m = scope.match(/^level:([a-z]+)$/))) {
    const levels = await credGetLevels(env);
    if (!levels[m[1]]) return deny('Unknown level', 400);
    if (m[1] === 'owner') return deny('The Owner always sees everything', 400);
    if (!ownerPowers) return deny('Only an Owner can change what a level can see');
  } else if ((m = scope.match(/^user:(\d+)$/))) {
    await ensureCredLevelTables(env);
    const t = await env.DB.prepare(`SELECT level FROM cred_users WHERE id = ?`).bind(parseInt(m[1])).first();
    if (!t) return deny('User not found', 404);
    if ((t.level === 'admin' || t.level === 'owner') && !ownerPowers) return deny('Only an Owner can change what an Admin or Owner can see');
  } else return deny('Bad scope', 400);
  const entries = Object.entries(b.rules || {}).filter(([k, v]) => /^[a-z0-9_-]{1,40}(:[a-z0-9_-]{1,40})?$/.test(k) && (v === 0 || v === 1)).slice(0, 500);
  if (scope.startsWith('level:') && entries.some(([, v]) => v === 1)) return deny('Level rules can only hide things', 400);
  await env.DB.prepare(`DELETE FROM access_rules WHERE scope = ?`).bind(scope).run();
  for (const [item, allow] of entries) {
    await env.DB.prepare(`INSERT INTO access_rules (scope, item, allow) VALUES (?, ?, ?)`).bind(scope, item, allow).run();
  }
  // `grant`: behind-the-scenes permissions the ticked pages/tabs need (the
  // Admin page picks them), added so a ticked tab actually works. Never admin.
  const grant = [...new Set((Array.isArray(b.grant) ? b.grant : []).filter(r => ['mobile', 'ops', 'mgmt', 'price'].includes(r)))];
  if (grant.length && (m = scope.match(/^level:([a-z]+)$/))) {
    const lv = (await credGetLevels(env))[m[1]];
    const roles = [...new Set([...(lv.roles || []), ...grant])];
    await env.DB.prepare(`UPDATE cred_levels SET roles = ? WHERE key = ?`).bind(JSON.stringify(roles), m[1]).run();
  } else if (grant.length && (m = scope.match(/^user:(\d+)$/))) {
    const uid = parseInt(m[1]);
    const u = await env.DB.prepare(`SELECT level FROM cred_users WHERE id = ?`).bind(uid).first();
    const lv = u && u.level ? (await credGetLevels(env))[u.level] : null;
    const own = ((await env.DB.prepare(`SELECT role FROM cred_user_roles WHERE user_id = ?`).bind(uid).all()).results || []).map(r => r.role);
    for (const r of grant) {
      if (own.includes(r) || (lv && (lv.roles || []).includes(r))) continue;
      await env.DB.prepare(`INSERT INTO cred_user_roles (user_id, role) VALUES (?, ?)`).bind(uid, r).run();
    }
  }
  return cors(new Response(JSON.stringify({ ok: true, saved: entries.length }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /admin/users/toggle-active  { userId, active: true|false }
async function adminToggleActive(request, env, session) {
  await ensureCredAuthTables(env);
  const body = await request.json().catch(() => ({}));
  const { userId, active } = body;
  if (!userId || typeof active !== 'boolean') {
    return cors(new Response(JSON.stringify({ ok: false, error: 'userId and active (boolean) required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  await ensureCredLevelTables(env);
  const t = await env.DB.prepare(`SELECT level, active, deleted_at FROM cred_users WHERE id = ?`).bind(userId).first();
  if (t && (t.level === 'admin' || t.level === 'owner') && !(await credCanActAsOwner(env, session))) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'Only an Owner can disable or enable an Admin or Owner' }), { status: 403, headers: { 'Content-Type': 'application/json' } }));
  }
  if (t && t.deleted_at && active) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'This user was removed — Restore them first' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  if (t && t.level === 'owner' && t.active && !active && (await credOwnerCount(env)) <= 1) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'This is the last Owner — make someone else Owner first' }), { status: 403, headers: { 'Content-Type': 'application/json' } }));
  }
  await env.DB.prepare(`UPDATE cred_users SET active = ? WHERE id = ?`).bind(active ? 1 : 0, userId).run();
  if (!active) {
    // Disabling immediately kills any live sessions too - a disabled
    // account shouldn't stay usable until its session happens to expire.
    await env.DB.prepare(`DELETE FROM cred_sessions WHERE user_id = ?`).bind(userId).run();
  }
  return cors(new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } }));
}

// POST /admin/users/remove   { userId }
// POST /admin/users/restore  { userId }
// Remove = take someone who no longer works here off the Users list. It is
// NOT a hard delete: the cred_users row stays so History, logs and the
// activity log still show their name, and the username can't be reused by
// someone else. They are signed out and can't sign in. Restore puts them
// back on the list, still Disabled until someone presses Enable.
async function adminRemoveUser(request, env, session, restore) {
  await ensureCredAuthTables(env);
  await ensureCredLevelTables(env);
  const J = (o, status) => cors(new Response(JSON.stringify(o), { status: status || 200, headers: { 'Content-Type': 'application/json' } }));
  const body = await request.json().catch(() => ({}));
  const userId = parseInt(body.userId);
  if (!userId) return J({ ok: false, error: 'userId required' }, 400);
  const t = await env.DB.prepare(`SELECT id, username, level, active, deleted_at FROM cred_users WHERE id = ?`).bind(userId).first();
  if (!t) return J({ ok: false, error: 'User not found' }, 404);
  if ((t.level === 'admin' || t.level === 'owner') && !(await credCanActAsOwner(env, session))) {
    return J({ ok: false, error: 'Only an Owner can remove or restore an Admin or Owner' }, 403);
  }
  const now = new Date().toISOString();
  if (restore) {
    if (!t.deleted_at) return J({ ok: false, error: 'This user is not removed' }, 400);
    await env.DB.prepare(`UPDATE cred_users SET deleted_at = NULL, deleted_by = NULL, active = 0 WHERE id = ?`).bind(userId).run();
    await logUserActivity(env, session.userId, 'admin_user_restored', { userId, username: t.username, by: session.username });
    return J({ ok: true });
  }
  if (t.deleted_at) return J({ ok: false, error: 'Already removed' }, 400);
  if (userId === session.userId) return J({ ok: false, error: 'You can’t remove yourself' }, 400);
  if (t.level === 'owner' && t.active && (await credOwnerCount(env)) <= 1) {
    return J({ ok: false, error: 'This is the last Owner — make someone else Owner first' }, 403);
  }
  await env.DB.prepare(`UPDATE cred_users SET active = 0, deleted_at = ?, deleted_by = ? WHERE id = ?`).bind(now, session.username, userId).run();
  await env.DB.prepare(`DELETE FROM cred_sessions WHERE user_id = ?`).bind(userId).run();
  await logUserActivity(env, session.userId, 'admin_user_removed', { userId, username: t.username, by: session.username });
  return J({ ok: true });
}

// GET /admin/activity?userId=&days=30 — raw activity log, optionally
// filtered to one user. Genuinely sparse/empty until apps are migrated
// to call logUserActivity() on real actions.
async function adminGetActivity(url, env) {
  await ensureActivityLogTable(env);
  const userId = url.searchParams.get('userId');
  const days = parseInt(url.searchParams.get('days')) || 30;
  const since = new Date(Date.now() - days * 86400000).toISOString();
  let rows;
  if (userId) {
    rows = await env.DB.prepare(`SELECT * FROM user_activity_log WHERE user_id = ? AND timestamp >= ? ORDER BY timestamp DESC LIMIT 500`).bind(userId, since).all();
  } else {
    rows = await env.DB.prepare(`SELECT * FROM user_activity_log WHERE timestamp >= ? ORDER BY timestamp DESC LIMIT 500`).bind(since).all();
  }
  return cors(new Response(JSON.stringify({ ok: true, activity: rows.results || [] }), { headers: { 'Content-Type': 'application/json' } }));
}

// ═══════════════════════════════════════════════════════════════════════════════
// ── REORDER: HISTORICAL SALES BACKFILL (one-time use) ────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════
// POST /reorder/backfill-weekly-sales?marketplace=amazon|shopify|ebay|walmart
// Body: [{ sku, period_start, period_end, units_ordered, asin?, fetched_at }, ...]
// Writes into the SAME D1 tables the weekly cron jobs already write to
// (amazon_sales_weekly etc.) - not a separate table - so historical and
// ongoing automated data blend into one continuous dataset. Safe to
// re-run: INSERT OR REPLACE on the real (sku, period_start) primary key
// means running this twice just overwrites with the same values, never
// duplicates or errors.
const REORDER_BACKFILL_TABLES = {
  amazon: 'amazon_sales_weekly', shopify: 'shopify_sales_weekly',
  ebay: 'ebay_sales_weekly', walmart: 'walmart_sales_weekly',
};

async function reorderBackfillWeeklySales(request, url, env) {
  const marketplace = (url.searchParams.get('marketplace') || '').toLowerCase();
  const table = REORDER_BACKFILL_TABLES[marketplace];
  if (!table) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'marketplace must be one of: amazon, shopify, ebay, walmart' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  const rows = await request.json().catch(() => null);
  if (!Array.isArray(rows) || !rows.length) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'body must be a non-empty array of rows' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }

  const hasAsin = marketplace === 'amazon';
  const salesCol = marketplace === 'amazon' ? 'ordered_product_sales' : 'sales_amount';

  const stmts = rows.map(r => {
    if (hasAsin) {
      return env.DB.prepare(
        `INSERT OR REPLACE INTO ${table} (sku, period_start, period_end, units_ordered, ${salesCol}, asin, fetched_at) VALUES (?,?,?,?,?,?,?)`
      ).bind(r.sku, r.period_start, r.period_end, r.units_ordered, r[salesCol] || 0, r.asin || '', r.fetched_at);
    }
    return env.DB.prepare(
      `INSERT OR REPLACE INTO ${table} (sku, period_start, period_end, units_ordered, ${salesCol}, fetched_at) VALUES (?,?,?,?,?,?)`
    ).bind(r.sku, r.period_start, r.period_end, r.units_ordered, r[salesCol] || 0, r.fetched_at);
  });

  let inserted = 0;
  for (let i = 0; i < stmts.length; i += 100) {
    await env.DB.batch(stmts.slice(i, i + 100));
    inserted += stmts.slice(i, i + 100).length;
  }

  return cors(new Response(JSON.stringify({ ok: true, marketplace, table, inserted }), { headers: { 'Content-Type': 'application/json' } }));
}

// ═══════════════════════════════════════════════════════════════════════════════
// ── REORDER: FBA CATALOG (which SKUs are active on FBA, and their ASIN) ─────
// ═══════════════════════════════════════════════════════════════════════════════
// Deliberately separate from the existing amazon_fba_inventory table -
// that one tracks listing-exists flags (afn/mfn) keyed by Amazon's
// randomized MSKU format, a different purpose and different SKU
// convention than what the reorder logic needs. This is just a simple
// SKU -> ASIN -> current stock list, in the real part-number format,
// with sales velocity intentionally left out since that already lives
// in the amazon_sales_weekly table - no need to duplicate it here.
async function ensureFbaCatalogTable(env) {
  await env.DB.prepare(`
    CREATE TABLE IF NOT EXISTS fba_catalog (
      sku TEXT PRIMARY KEY,
      asin TEXT, fnsku TEXT, product_name TEXT,
      available INTEGER, updated_at TEXT
    )
  `).run().catch(()=>{});
}

// POST /reorder/fba-catalog-import
// Body: [{ sku, asin, fnsku, product_name, available, updated_at }, ...]
// Safe to re-run - INSERT OR REPLACE on the sku primary key.
async function reorderFbaCatalogImport(request, env) {
  await ensureFbaCatalogTable(env);
  const rows = await request.json().catch(() => null);
  if (!Array.isArray(rows) || !rows.length) {
    return cors(new Response(JSON.stringify({ ok: false, error: 'body must be a non-empty array of rows' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
  }
  const stmts = rows.map(r => env.DB.prepare(
    `INSERT OR REPLACE INTO fba_catalog (sku, asin, fnsku, product_name, available, updated_at) VALUES (?,?,?,?,?,?)`
  ).bind(r.sku, r.asin || '', r.fnsku || '', r.product_name || '', r.available || 0, r.updated_at));

  let inserted = 0;
  for (let i = 0; i < stmts.length; i += 100) {
    await env.DB.batch(stmts.slice(i, i + 100));
    inserted += stmts.slice(i, i + 100).length;
  }
  return cors(new Response(JSON.stringify({ ok: true, inserted }), { headers: { 'Content-Type': 'application/json' } }));
}


