// GET /walmart/test-connection — read-only connectivity check, same
// pattern as ebayAccountDiscover: prove the credentials actually work
// before building anything that writes/creates listings.
// GET /walmart/check-version?version=... — safe, read-only check of
// whether this account's item spec accepts a given version, using the
// taxonomy endpoint (which requires a valid feedType+version to return
// anything useful). Built after repeated rounds of guessing item-field
// structure blind — lets the actual version be confirmed without
// risking another real feed submission each time.
// GET /walmart/catalog-search?upc=... — the actual missing step: checks
// whether this UPC already exists somewhere in Walmart's broader catalog
// (sold by another seller), which determines whether MP_ITEM (full new
// item setup — what's been submitted this whole time) or MP_ITEM_MATCH
// (link an offer to an existing catalog item) is actually correct.
// responseFormat=SPEC additionally returns the exact itemSpecPayload
// structure to use for whichever path applies — read-only, safe to call
// before submitting another real feed.
// POST /walmart/spreadsheet-data — Body: { baseSkus: [...] }
// Maps product_catalog rows to Walmart's exact field structure, confirmed
// directly from the real spec spreadsheet (omni-marketplace-en-external-
// 5_0_20260608-18_15_07.xlsx) — the frontend turns this JSON into an
// actual downloadable .xlsx matching that template exactly, for upload
// through Seller Center's UI (the path proven to work for this account,
// unlike the API route). One row per pack size, matching the same
// individual-listing convention as Amazon/eBay.
async function walmartSpreadsheetData(request, env) {
  if (!env.DB) return cors(new Response(JSON.stringify({ ok: false, error: 'D1 not available' }), { status: 503, headers: { 'Content-Type': 'application/json' } }));
  try {
    const body = await request.json().catch(() => ({}));
    const baseSkus = Array.isArray(body.baseSkus) ? body.baseSkus : [];
    if (!baseSkus.length) return cors(new Response(JSON.stringify({ ok: false, error: 'baseSkus array required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    const rows = [];
    const skipped = [];
    for (const baseSku of baseSkus) {
      const catalogRows = await d1All(env, 'SELECT * FROM product_catalog WHERE base_sku=? ORDER BY pack_qty ASC', [baseSku.toUpperCase()]);
      if (!catalogRows.length) { skipped.push({ baseSku, reason: 'Not found in product_catalog' }); continue; }

      for (const row of catalogRows) {
        if (!row.upc) { skipped.push({ baseSku, sku: row.sku, reason: 'No UPC' }); continue; }
        // BUGFIX: confirmed via a real user report — this combined-OR
        // message required a follow-up round trip to find out which
        // specific field was actually missing. Checks each one
        // individually now and names exactly what's missing.
        const missing = [];
        if (!row.title_short) missing.push('title_short');
        if (!row.starting_price) missing.push('starting_price');
        if (!row.weight_lbs) missing.push('weight_lbs');
        if (!row.walmart_product_type) missing.push('walmart_product_type');
        if (missing.length) {
          skipped.push({ baseSku, sku: row.sku, reason: 'Missing: ' + missing.join(', ') });
          continue;
        }
        const bullets = [row.bullet_1, row.bullet_2, row.bullet_3, row.bullet_4].filter(Boolean); // template has 4 keyFeatures columns, not 5

        // MAJOR BUGFIX: confirmed via a real pasted-result cross-checked
        // against the actual template file — my very first reading of
        // this template (many messages ago) miscounted the column
        // offset. Data genuinely starts at column D (index 4, 1-indexed),
        // and previous versions only included ~21 of the real 93
        // columns, silently skipping required fields (Material, Has
        // Written Warranty, Net Content Unit/Measure) that sat BETWEEN
        // fields that were included — shifting everything after them
        // into the wrong column when pasted. Also reverted the GTIN-14
        // padding — the user confirmed this account's Product ID field
        // wants the plain 12-digit UPC, not a padded 14-digit GTIN.
        //
        // Uses an explicit column-number -> value map, placed into a
        // fixed 93-element array programmatically, rather than manually
        // counting blank placeholder strings — a first attempt at that
        // manual approach came out to 86 elements instead of 93,
        // exactly the kind of counting error this avoids entirely.
        function buildWalmartRow(fields) {
          const arr = new Array(93).fill('');
          for (const col in fields) arr[Number(col) - 4] = fields[col]; // column 4 in the real template = array index 0
          return arr;
        }
        const orderedRow = buildWalmartRow({
          4: row.sku, 5: row.walmart_product_type, 6: 'UPC', 7: row.upc, 8: row.title_short, 9: row.manufacturer || 'XFITTING',
          10: row.starting_price, 11: row.weight_lbs, 12: WALMART_DEFAULTS.countryOfOrigin, 13: 'New',
          14: WALMART_DEFAULTS.fulfillmentCenterID, 15: WALMART_DEFAULTS.quantity,
          17: row.description || '', 18: bullets[0] || '', 19: bullets[1] || '', 20: bullets[2] || '', 21: bullets[3] || '',
          // BUGFIX: confirmed via a real pasted result cross-checked
          // against the real template — the true order is Unit (Y),
          // Measure (Z), Material (AA). Previous version had Material
          // first, then Unit, then Measure — reversed from reality,
          // which is exactly why "Lead-Free Brass" showed up in the
          // Unit column, "Count" in Measure, and "1" in Material.
          22: row.image_url_1 || '', 23: 'No', 24: 'No', 25: 'Count', 26: 1, 27: row.material || '',
          61: row.walmart_product_type === 'Valves' ? (row.fitting_type || '') : '',
        });
        rows.push(orderedRow);
      }
    }

    if (!rows.length) return cors(new Response(JSON.stringify({ ok: false, error: 'No rows ready — check UPC, title_short, starting_price, weight_lbs, and walmart_product_type are all set', skipped }), { status: 400, headers: { 'Content-Type': 'application/json' } }));

    return cors(new Response(JSON.stringify({ ok: true, rowCount: rows.length, skipped, rows }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

async function walmartCatalogSearch(url, env) {
  try {
    const upc = url.searchParams.get('upc');
    if (!upc) return cors(new Response(JSON.stringify({ ok: false, error: 'upc parameter required' }), { status: 400, headers: { 'Content-Type': 'application/json' } }));
    const token = await getWalmartToken(env);

    const res = await fetch(`https://marketplace.walmartapis.com/v3/items/walmart/search?upc=${encodeURIComponent(upc)}&responseFormat=SPEC`, {
      headers: {
        'WM_SEC.ACCESS_TOKEN': token,
        'WM_QOS.CORRELATION_ID': crypto.randomUUID(),
        'WM_SVC.NAME': 'Walmart Marketplace',
        'Accept': 'application/json',
      },
    });
    const data = await res.json();
    if (!res.ok) return cors(new Response(JSON.stringify({ ok: false, error: 'Catalog search failed: HTTP ' + res.status, detail: data }), { status: 500, headers: { 'Content-Type': 'application/json' } }));

    const item = (data.items || [])[0] || null;
    return cors(new Response(JSON.stringify({
      ok: true, upc,
      foundInWalmartCatalog: !!item,
      feedTypeToUse: item && item.itemSpecPayload ? item.itemSpecPayload.MPItemFeedHeader?.feedType || 'MP_ITEM_MATCH (found)' : 'MP_ITEM (not found)',
      rawResponse: data,
    }), { headers: { 'Content-Type': 'application/json' } }));
  } catch (e) {
    return cors(new Response(JSON.stringify({ ok: false, error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } }));
  }
}

